// workspaceSummaryAllColumns is the column list for full-entity reads, sorted for determinism.
var workspaceSummaryAllColumns = []string{"product_count", "workspace_id", "workspace_name"}

// scanWorkspaceSummaries scans rows into WorkspaceSummary entities using a column-name switch.
// Handles both scan target shapes (direct, wrapped) without reflection.
func scanWorkspaceSummaries(rows database.Rows, columns []string) ([]*WorkspaceSummary, error) {
	var result []*WorkspaceSummary
	for rows.Next() {
		w := &WorkspaceSummary{}

		targets := make([]any, len(columns))
		for idx, col := range columns {
			switch col {
			case "workspace_id":
				targets[idx] = &w.WorkspaceID
			case "workspace_name":
				targets[idx] = &w.WorkspaceName
			case "product_count":
				targets[idx] = &w.ProductCount
			}
		}

		if err := rows.Scan(targets...); err != nil {
			return nil, fmt.Errorf("scan workspace_summary: %w", err)
		}

		result = append(result, w)
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("iterate workspace_summary rows: %w", err)
	}
	return result, nil
}

// GetMany returns workspace_summaries matching the given filter, field selection, and sort criteria.
func (c *workspaceSummaryClient) GetMany(ctx context.Context, input *GetWorkspaceSummariesInput, opts ...func(*CallOptions[WorkspaceSummaryFieldOptions])) ([]*WorkspaceSummary, error) {
	// A nil input is the zero-value input — no filter, no sorts, no
	// limit. Normalized before the hook context is built, so a hook never sees
	// a nil Input either.
	if input == nil {
		input = &GetWorkspaceSummariesInput{}
	}
	options := resolveCallOptions(opts)
	result, err := c.executeQuery(ctx, options.SkipHooks, &hook.QueryContext{
		Op: hook.OpGetMany, Table: TableWorkspaceSummaries, Schema: "",
		Input: input, CallOptions: options,
	}, func(ctx context.Context, q *hook.QueryContext) (any, error) {
		conn := database.Conn(ctx, c.querier)

		// FieldOptions from CallOptions — nil means all columns
		fieldOptions := options.FieldOptions

		// Nothing selected — return early
		if fieldOptions != nil && !fieldOptions.HasSelectedColumns() {
			return nil, nil
		}

		// Determine columns from FieldOptions. A narrowed projection still
		// carries the columns this call structurally requires — the cursor keys
		// an internal caller declares. An all-false FieldOptions is untouched:
		// it short-circuits above.
		columns := workspaceSummaryAllColumns
		if fieldOptions != nil {
			if selected := fieldOptions.Columns(); len(selected) > 0 {
				columns = unionColumns(selected, input.requiredColumns...)
			}
		}

		// Build conditions from filter
		var conds []sql.Condition
		if input.Filter != nil {
			conds = input.Filter.ToConditions(c.dialect)
		}

		// Append internal conditions (e.g., keyset conditions from Connection)
		conds = append(conds, input.conditions...)

		// Resolve limit/offset to pointers for the builder.
		// nil → no clause, *0 (via new(0)) → no clause, *N → LIMIT/OFFSET N.
		var limitPtr *int
		if input.Limit != nil {
			if v := *input.Limit; v > 0 {
				limitPtr = new(v)
			}
		} else if c.queryLimit > 0 {
			limitPtr = new(c.queryLimit)
		}
		var offsetPtr *int
		if input.Offset != nil {
			if v := *input.Offset; v > 0 {
				offsetPtr = new(v)
			}
		}

		query, args := sql.BuildSelect(c.dialect, c.table, sql.SelectOptions{
			Columns:    columns,
			Conditions: conds,
			OrderBy:    input.Sorts,
			Limit:      limitPtr,
			Offset:     offsetPtr,
		})

		rows, err := conn.Query(ctx, query, args...)
		if err != nil {
			return nil, fmt.Errorf("get workspace_summaries: %w", err)
		}
		defer rows.Close()

		workspaceSummaries, err := scanWorkspaceSummaries(rows, columns)
		if err != nil {
			return nil, err
		}

		return workspaceSummaries, nil
	})
	if err != nil {
		return nil, err
	}
	if result == nil {
		return nil, nil
	}
	return result.([]*WorkspaceSummary), nil
}

// Count returns the number of workspace_summaries matching the given filter.
// A nil filter counts all workspace_summaries.
func (c *workspaceSummaryClient) Count(ctx context.Context, filter *WorkspaceSummaryFilter, opts ...func(*CallOptions[WorkspaceSummaryFieldOptions])) (int64, error) {
	options := resolveCallOptions(opts)
	result, err := c.executeQuery(ctx, options.SkipHooks, &hook.QueryContext{
		Op: hook.OpCount, Table: TableWorkspaceSummaries, Schema: "",
		Input: filter, CallOptions: options,
	}, func(ctx context.Context, q *hook.QueryContext) (any, error) {
		conn := database.Conn(ctx, c.querier)

		var conds []sql.Condition
		if filter != nil {
			conds = filter.ToConditions(c.dialect)
		}

		query, args := sql.BuildCount(c.dialect, c.table, conds)

		var count int64
		if err := conn.QueryRow(ctx, query, args...).Scan(&count); err != nil {
			return int64(0), fmt.Errorf("count workspace_summaries: %w", err)
		}
		return count, nil
	})
	if err != nil {
		return 0, err
	}
	return result.(int64), nil
}

// Paginate returns a page of workspace_summaries with total count for offset-based pagination.
// A nil filter paginates all workspace_summaries.
func (c *workspaceSummaryClient) Paginate(ctx context.Context, input PaginateInput[WorkspaceSummaryFilter], opts ...func(*CallOptions[WorkspaceSummaryFieldOptions])) (*PaginateResult[WorkspaceSummary], error) {
	options := resolveCallOptions(opts)
	result, err := c.executeQuery(ctx, options.SkipHooks, &hook.QueryContext{
		Op: hook.OpPaginate, Table: TableWorkspaceSummaries, Schema: "",
		Input: input, CallOptions: options,
	}, func(ctx context.Context, q *hook.QueryContext) (any, error) {
		// Internal calls with SkipHooks to prevent nested hook invocation
		internalOpts := func(o *CallOptions[WorkspaceSummaryFieldOptions]) {
			*o = options
			o.SkipHooks = true
		}

		// Total count (delegates to Count — both are always generated)
		totalCount, err := c.Count(ctx, input.Filter, internalOpts)
		if err != nil {
			return nil, fmt.Errorf("paginate workspace_summaries count: %w", err)
		}

		// Page data via GetMany (handles FieldOptions)
		workspaceSummaries, err := c.GetMany(ctx, &GetWorkspaceSummariesInput{
			Filter: input.Filter,
			Sorts:  input.Sort,
			Limit:  &input.Limit,
			Offset: &input.Offset,
		}, internalOpts)
		if err != nil {
			return nil, fmt.Errorf("paginate workspace_summaries: %w", err)
		}

		return &PaginateResult[WorkspaceSummary]{
			Items:      workspaceSummaries,
			TotalCount: totalCount,
			Offset:     input.Offset,
			Limit:      input.Limit,
			HasMore:    int64(input.Offset+input.Limit) < totalCount,
		}, nil
	})
	if err != nil {
		return nil, err
	}
	return result.(*PaginateResult[WorkspaceSummary]), nil
}

// WorkspaceSummaryFilter provides type-safe filtering for the workspace_summaries table.
type WorkspaceSummaryFilter struct {
	ProductCount  *comparator.Number[int64] `json:"product_count"`
	WorkspaceID   *comparator.String        `json:"workspace_id"`
	WorkspaceName *comparator.String        `json:"workspace_name"`
	And           []*WorkspaceSummaryFilter `json:"and"`
	Or            []*WorkspaceSummaryFilter `json:"or"`
}

// ToConditions converts the filter to a slice of SQL conditions.
//
// A nil receiver contributes no conditions. Two callers depend on that. The
// *Where methods dereference their filter only here and document a nil one as
// the empty-filter case, so this is what makes ErrEmptyFilter reachable instead
// of a nil dereference. And a nil entry inside and / or is skipped rather than
// fatal, matching the "an unset member contributes no SQL" rule the
// relationship members already follow.
func (f *WorkspaceSummaryFilter) ToConditions(dialect sql.Dialect, opts ...FilterOption) []sql.Condition {
	if f == nil {
		return nil
	}

	var conds []sql.Condition

	if f.ProductCount != nil {
		conds = append(conds, f.ProductCount.Parse(dialect.QuoteIdentifier("product_count"), dialect)...)
	}

	if f.WorkspaceID != nil {
		conds = append(conds, f.WorkspaceID.Parse(dialect.QuoteIdentifier("workspace_id"), dialect)...)
	}

	if f.WorkspaceName != nil {
		conds = append(conds, f.WorkspaceName.Parse(dialect.QuoteIdentifier("workspace_name"), dialect)...)
	}

	for _, sub := range f.And {
		subConds := sub.ToConditions(dialect, opts...)
		if len(subConds) > 0 {
			conds = append(conds, sql.And(subConds...))
		}
	}

	// A filter object's own fields are always conjunctive, so each or member
	// contributes sql.And of its own conditions and the members are OR-ed
	// together as ONE group condition. Appending a per-member
	// sql.Or instead hands the caller N conditions, and buildWhere joins those
	// with AND — turning or: [A, B] into A AND B, while simultaneously OR-ing a
	// single member's own fields against each other.
	//
	// The group is appended only when some member compiled to something:
	// sql.Or of nothing expands to a literal "()", which buildWhere keeps
	// because it is not the empty string, yielding invalid SQL.
	var orGroup []sql.Condition
	for _, sub := range f.Or {
		subConds := sub.ToConditions(dialect, opts...)
		if len(subConds) > 0 {
			orGroup = append(orGroup, sql.And(subConds...))
		}
	}
	if len(orGroup) > 0 {
		conds = append(conds, sql.Or(orGroup...))
	}

	return conds
}

